-- 5674: подпись кассира + сид факсимиле (JPEG из PDF)
-- Исходники: «подпись Васильевой О.В. касса Соф.pdf», «Фахрутдинова.pdf», «Герасимова.pdf»
-- type / image_type в stored_resource — строки Image / Signature

ALTER TABLE organization_versions
	ADD COLUMN signature_cashier_id INT NULL AFTER signature_accountant_id;

ALTER TABLE receipt_correction_explanatory_notes
	ADD COLUMN signer_signature_id INT NULL AFTER signer_name;

UPDATE organization_versions
SET signature_cashier_id = signature_leader_id
WHERE signature_cashier_id IS NULL AND signature_leader_id IS NOT NULL;

INSERT INTO stored_resource (name, binary_file, type, image_type)
SELECT 'Подпись кассира Васильева О.В.', UNHEX(''), 'Image', 'Signature'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM stored_resource sr WHERE sr.name = 'Подпись кассира Васильева О.В.');

INSERT INTO stored_resource (name, binary_file, type, image_type)
SELECT 'Подпись кассира Фахрутдинова Н.В.', UNHEX(''), 'Image', 'Signature'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM stored_resource sr WHERE sr.name = 'Подпись кассира Фахрутдинова Н.В.');

INSERT INTO stored_resource (name, binary_file, type, image_type)
SELECT 'Подпись кассира Герасимова Н.П.', UNHEX(''), 'Image', 'Signature'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM stored_resource sr WHERE sr.name = 'Подпись кассира Герасимова Н.П.');

UPDATE organization_versions ov
INNER JOIN organizations o ON o.id = ov.organization_id
INNER JOIN stored_resource sr ON sr.name = 'Подпись кассира Васильева О.В.'
SET ov.signature_cashier_id = sr.id
WHERE (o.name LIKE '%Веселый Водовоз Юг%' OR o.full_name LIKE '%Веселый Водовоз Юг%')
	AND (ov.end_date IS NULL OR ov.end_date >= NOW());

UPDATE organization_versions ov
INNER JOIN organizations o ON o.id = ov.organization_id
INNER JOIN stored_resource sr ON sr.name = 'Подпись кассира Фахрутдинова Н.В.'
SET ov.signature_cashier_id = sr.id
WHERE (o.name LIKE '%Веселый Водовоз Восток%' OR o.full_name LIKE '%Веселый Водовоз Восток%')
	AND (ov.end_date IS NULL OR ov.end_date >= NOW());

UPDATE organization_versions ov
INNER JOIN organizations o ON o.id = ov.organization_id
INNER JOIN stored_resource sr ON sr.name = 'Подпись кассира Герасимова Н.П.'
SET ov.signature_cashier_id = sr.id
WHERE (o.name LIKE '%Губернаторов%' OR o.full_name LIKE '%Губернаторов%')
	AND (ov.end_date IS NULL OR ov.end_date >= NOW());

